/bin/bash -lc 'run_dir=$(ls -dt "$TMPDIR"/adina.* | head -1)
python3 - "$run_dir/courses.html" <<'"'PY'
from bs4 import BeautifulSoup
from pathlib import Path
p=Path(__import__('sys').argv[1])
s=BeautifulSoup(p.read_text(errors='ignore'),'html.parser')
for x in s(['script','style','noscript','svg','nav','footer']): x.decompose()
print('HEADINGS')
for tag in s.find_all(['h1','h2','h3','h4','h5','h6']):
 t=' '.join(tag.get_text(' ',strip=True).split())
 if t: print(tag.name, repr(t))
print('\\nTABLES')
for i,table in enumerate(s.find_all('table'),1):
 print(f'--TABLE {i}--')
 for tr in table.find_all('tr'):
  cells=[' '.join(c.get_text(' ',strip=True).split()) for c in tr.find_all(['th','td'])]
  if any(cells): print(' | '.join(cells))
print('\\nCONTENT BLOCK TEXT')
main=s.find('main') or s
# print only text paragraphs/strong/div maybe selected exact phrase lines
for t in main.find_all(string=True):
 v=' '.join(t.split())
 if v and any(k.lower() in v.lower() for k in ['engineering courses','diploma','undergraduate','postgraduate','civil engineering','computer science','electrical','mechanical','thermal','vlsi','b.pharm','m.pharm']):
  print(v)
PY"

